    usleep(50000); // 50ms delay
    CGEventPost(kCGHIDEventTap, mouseUp);

    CFRelease(mouseDown);
    CFRelease(mouseUp);

    NSLog(@"Tap sent to coordinates: (%.0f, %.0f)", menuButtonLocation.x, menuButtonLocation.y);

