#import <Foundation/Foundation.h>
#import <Cocoa/Cocoa.h>

int main() {
    // First, get all windows and find the Simulator window
    NSArray *windows = (__bridge NSArray *)CGWindowListCopyWindowInfo(kCGWindowListOptionAll, kCGNullWindowID);

    CGWindowID simulatorWindowID = 0;
    for (NSDictionary *window in windows) {
        NSString *appName = window[(id)kCGWindowOwnerName];
        NSDictionary *bounds = window[(id)kCGWindowBounds];
        NSNumber *windowNumber = window[(id)kCGWindowNumber];

        if ([appName containsString:@"Simulator"]) {
            CGFloat width = [bounds[@"Width"] doubleValue];
            CGFloat height = [bounds[@"Height"] doubleValue];

            // Find the main simulator window (500x1232)
            if (width == 500 && height == 1232) {
                simulatorWindowID = [windowNumber unsignedIntValue];
                NSLog(@"Found main simulator window: %u", simulatorWindowID);
                break;
            }
        }
    }

    if (simulatorWindowID) {
        // Click in the center of the simulator window to focus it
        CGPoint centerPoint = CGPointMake(250, 600);

        CGEventRef mouseEvent = CGEventCreateMouseEvent(NULL, kCGEventLeftMouseDown, centerPoint, kCGMouseButtonLeft);
        CGEventPost(kCGHIDEventTap, mouseEvent);
        usleep(50000);
        CFRelease(mouseEvent);

        mouseEvent = CGEventCreateMouseEvent(NULL, kCGEventLeftMouseUp, centerPoint, kCGMouseButtonLeft);
        CGEventPost(kCGHIDEventTap, mouseEvent);
        CFRelease(mouseEvent);

        usleep(200000); // Wait for focus

        // Now click the menu button
        CGPoint menuPoint = CGPointMake(55, 149);
        mouseEvent = CGEventCreateMouseEvent(NULL, kCGEventLeftMouseDown, menuPoint, kCGMouseButtonLeft);
        CGEventPost(kCGHIDEventTap, mouseEvent);
        usleep(50000);
        CFRelease(mouseEvent);

        mouseEvent = CGEventCreateMouseEvent(NULL, kCGEventLeftMouseUp, menuPoint, kCGMouseButtonLeft);
        CGEventPost(kCGHIDEventTap, mouseEvent);
        CFRelease(mouseEvent);

        NSLog(@"Clicked to focus and then tapped menu button");
    }

    return 0;
}
EOF
